// The browser's YIN against the desktop's, frame by frame, on a real take.
//
// `web/test/yin.json` holds the frames the REAL Python estimator
// (`core/pitch.py`, driven through `YinBlock` at the live geometry) reads on two
// EXCERPTS of `demo.wav`, generated by `scripts/export_web_fixtures.py`. This
// test recomputes every one of them here from the same samples: the two paths
// share the formula but not the arithmetic (numpy's rfft against a radix-2 FFT),
// so what holds them together is a MEASURED bound, not a hope.
//
// Two excerpts rather than the whole take: the ASCENT carries every scale degree
// the melody sings (C4 259 Hz to C5 523 Hz) and the TAIL carries the final tonic
// and the low C2 pedal, whose period sits at the lag search's own limit. The
// descent repeats pitches, and the middle of the take adds bytes, not bands —
// the coverage test below refuses a cut that loses either end of the range.
//
// Measured on both excerpts (470 frames, 446 voiced): 0.000013 cents, 5e-7 in
// d', 0 voicing disagreements. The bounds below leave room for float noise but
// not for drift — one lag sample at 440 Hz is about 40 cents, so a widened bound
// would be a decision, never a tweak.
//
// `demo.wav` is gitignored (`python scripts/make_demo.py` writes it, the same
// bytes every time), so this file skips rather than fails where the take is
// absent; the digest in the fixture refuses a different file of that name.
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import test from "node:test";
import assert from "node:assert/strict";

import { FMIN } from "../constants.js";
import { YinBlock } from "../yin.js";
import { readPcm16Mono } from "./wav.mjs";

const FIXTURE = fileURLToPath(new URL("./yin.json", import.meta.url));
const TAKE = fileURLToPath(new URL("../../demo.wav", import.meta.url));

const MAX_CENTS = 0.5;
const MAX_QUALITY = 0.01;

const fixture = JSON.parse(readFileSync(FIXTURE, "utf8"));

test("every frame's pitch matches the desktop's YIN on the demo take", (t) => {
  if (!existsSync(TAKE)) {
    t.skip("demo.wav is absent: run `python scripts/make_demo.py`");
    return;
  }
  const digest = createHash("sha256").update(readFileSync(TAKE)).digest("hex");
  assert.equal(digest, fixture.source.sha256, `${fixture.source.name} is not the take this fixture was built from`);

  const { sampleRate, samples } = readPcm16Mono(TAKE);
  assert.equal(sampleRate, fixture.source.sr);
  assert.equal(samples.length, fixture.source.samples);

  for (const excerpt of fixture.excerpts) {
    const chunk = samples.subarray(excerpt.start, excerpt.start + excerpt.samples);
    assert.equal(chunk.length, excerpt.samples, `${excerpt.name}: the two sides built different signals`);

    const yin = new YinBlock(sampleRate, {
      window: fixture.geometry.window,
      hop: fixture.geometry.hop,
    });
    const frames = yin.pushWithQuality(chunk).map((frame) => [
      frame.t,
      Number.isFinite(frame.hz) ? frame.hz : null,
      Number.isFinite(frame.quality) ? frame.quality : null,
    ]);
    assert.equal(
      frames.length,
      excerpt.frames.length,
      `${excerpt.name}: the two estimators disagree on how many frames it holds`,
    );

    let worstCents = 0;
    let worstQuality = 0;
    for (const [index, expected] of excerpt.frames.entries()) {
      const [t, hz, quality] = frames[index];
      assert.ok(
        Math.abs(t - expected[0]) < 1e-6,
        `${excerpt.name} frame ${index}: time ${t} vs ${expected[0]}`,
      );
      if (expected[1] === null || hz === null) {
        // A voicing disagreement is not a rounding difference: one engine calls
        // it a note and the other calls it silence, which the take would show.
        assert.equal(
          hz,
          expected[1],
          `${excerpt.name} frame ${index}: voicing differs (${hz} vs ${expected[1]})`,
        );
        continue;
      }
      const cents = Math.abs(1200 * Math.log2(hz / expected[1]));
      worstCents = Math.max(worstCents, cents);
      worstQuality = Math.max(worstQuality, Math.abs(quality - expected[2]));
    }
    assert.ok(worstCents <= MAX_CENTS, `${excerpt.name}: worst pitch difference ${worstCents.toFixed(4)} cents`);
    assert.ok(worstQuality <= MAX_QUALITY, `${excerpt.name}: worst periodicity difference ${worstQuality.toFixed(5)}`);
  }
});

test("the excerpts still span every pitch the take visits", () => {
  // Cutting the take down to an excerpt is only worth it if the RANGE survives:
  // a head-only crop loses the pedal (the low-lag limit), a tail-only crop loses
  // the octave above it — and both would pass every bound in the test above.
  const voiced = fixture.excerpts.flatMap((excerpt) =>
    excerpt.frames.map(([, hz]) => hz).filter((hz) => hz !== null),
  );
  assert.ok(voiced.length > 100, `only ${voiced.length} voiced frames are pinned`);
  const lowest = Math.min(...voiced);
  const highest = Math.max(...voiced);
  assert.ok(lowest <= FMIN * 1.05, `no frame near FMIN (lowest ${lowest.toFixed(2)} Hz)`);
  assert.ok(highest >= 500, `no frame at the top of the take (highest ${highest.toFixed(2)} Hz)`);
  // and a real voicing break, where a port's frame counting shows
  assert.ok(
    fixture.excerpts.some((excerpt) => excerpt.frames.some(([, hz]) => hz === null)),
    "no unvoiced frame left in the excerpts",
  );
});
